import{statuses,seriesCatalog,demoBooks}from'./data.js';import{openDB,saveBooks,validateBackup}from'./storage.js';import{searchMetadata}from'./metadata.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const norm=s=>String(s??'').toLocaleLowerCase('uk').replace(/[’ʼ`‘]/g,"'").normalize('NFKC');const prefs=JSON.parse(localStorage.getItem('library-prefs')||'{}');let books=[],demo=true,page='library',view=prefs.view||'grid',sort=prefs.sort||'title',direction=prefs.direction||1,group='',query='',filters={},scrollY=0;const names={library:'Моя бібліотека',series:'Цикли',wish:'Хочу прочитати',quotes:'Цитати'};let timer;function toast(message,undo){clearTimeout(timer);$('#toast').innerHTML=esc(message)+(undo?'<button id="undo">Скасувати</button>':'');if(undo)$('#undo').onclick=undo;timer=setTimeout(()=>$('#toast').innerHTML='',9000)}function remember(){localStorage.setItem('library-prefs',JSON.stringify({view,sort,direction}))}function current(){return demo?demoBooks:books}async function persist(next){await saveBooks(next);books=next}function modal(html){$('#modal').innerHTML=html;$('#modal').showModal();$('#modal').scrollTop=0;$('#modal').querySelector('.close')?.addEventListener('click',()=>$('#modal').close())}function head(title){return `<div class="modal-head"><h2>${esc(title)}</h2><button class="close" aria-label="Закрити">×</button></div>`}function cover(b){return b.cover?`<img class="cover" src="${esc(b.cover)}" alt="Обкладинка ${esc(b.title)}">`:`<div class="illustrated" style="--cover:${/^#[a-f0-9]{6}$/i.test(b.color)?b.color:'#385147'}"><span class="orn">❧</span><strong>${esc(b.title)}</strong><small>${esc(b.work.authors||'Особистий альбом')}</small><span class="orn">✦</span></div>`}function stars(b){return b.rating==null?'Без оцінки':`★ ${Number(b.rating).toLocaleString('uk')} <span style="opacity:.45">/ 5</span>`}function bookCard(b){return `<article class="book"><button class="cover-button" data-open="${b.id}">${cover(b)}</button>${b.favorite?'<span class="fav" aria-label="Улюблена">♥</span>':''}<div><h3><button class="link" style="font:inherit;color:inherit" data-open="${b.id}">${esc(b.title)}</button></h3><button class="link" data-author="${esc(b.work.authors)}">${esc(b.work.authors||'Автор не зазначений')}</button></div><div class="book-meta"><span class="stars">${stars(b)}</span><span class="status ${b.status==='Хочу прочитати'?'want':''}">${esc(b.status)}</span></div></article>`}function values(key){return [...new Set(current().flatMap(b=>key==='genres'?b.work.genres:[key==='status'?b.status:b.work[key]]).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'uk'))}function renderFilters(){const opts=(key,label,vals)=>`<label>${label}<select data-filter="${key}"><option value="">Усі</option>${vals.map(v=>`<option ${filters[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;$('#filters').innerHTML=opts('genres','Жанр',values('genres'))+opts('authors','Автор',values('authors'))+opts('series','Цикл',values('series'))+opts('status','Статус',statuses)+opts('rating','Мінімальна оцінка',['1','1.5','2','2.5','3','3.5','4','4.5','5'])+opts('favorite','Улюблені',['Так'])+opts('owned','Є вдома',['Так','Ні']);$('#filters').querySelectorAll('select').forEach(s=>s.onchange=()=>{filters[s.dataset.filter]=s.value;render()})}function matching(){return current().filter(b=>(page!=='wish'||b.status==='Хочу прочитати')&&norm([b.title,b.work.original,b.work.authors,b.work.series].join(' ')).includes(norm(query))&&Object.entries(filters).every(([k,v])=>!v||(k==='genres'?b.work.genres.includes(v):k==='rating'?b.rating!=null&&b.rating>=+v:k==='favorite'?b.favorite:k==='owned'?b.owned===(v==='Так'):k==='status'?b.status===v:b.work[k]===v))).sort((a,b)=>{const val=x=>sort==='title'?x.title:sort==='rating'?x.rating:sort==='added'?x.added:x.work[sort];let x=val(a),y=val(b);if(x==null||x==='')return y==null||y===''?0:1;if(y==null||y==='')return -1;return direction*(typeof x==='number'?x-y:String(x).localeCompare(String(y),'uk'))})}function render(){ $('#nav').innerHTML=Object.entries(names).map(([k,v],i)=>`<button data-page="${k}" class="${page===k?'active':''}"><span aria-hidden="true">${['▤','♧','◇','❞'][i]}</span>　${v}</button>`).join('');$('#nav').querySelectorAll('button').forEach(b=>b.onclick=()=>{page=b.dataset.page;filters={};query='';$('#search').value='';render()});$('#pageTitle').textContent=names[page];$('#chapter').textContent=['РОЗДІЛ I','РОЗДІЛ II','РОЗДІЛ III','РОЗДІЛ IV'][Object.keys(names).indexOf(page)];$('#subtitle').textContent={library:'Знайомі світи. Нові відкриття. Усе на своїх полицях.',series:'Історії, з якими ще не хочеться прощатися.',wish:'Книги, що чекають на свою мить.',quotes:'Слова, які хочеться залишити з собою.'}[page];$('#personal').classList.toggle('active',!demo);$('#demo').classList.toggle('active',demo);$('#demoNotice').textContent=demo?'Ви переглядаєте демонстраційний альбом. Ці книги не входять до вашої колекції. Обкладинки — художні ілюстрації.':'Ваша особиста колекція · зберігається в цьому браузері';$('#libraryTools').hidden=['series','quotes'].includes(page);$('#grid').classList.toggle('active',view==='grid');$('#list').classList.toggle('active',view==='list');$('#sort').value=sort;$('#direction').textContent=direction===1?'↑':'↓';renderFilters();$('#activeFilters').innerHTML=Object.entries(filters).filter(([,v])=>v).map(([,v])=>`<span class="chip">${esc(v)}</span>`).join('');if(page==='series'){renderSeries();return}if(page==='quotes'){renderQuotes();return}const result=matching();$('#count').textContent=`${result.length} із ${current().length} книг`;if(!result.length){$('#content').innerHTML=`<div class="empty"><div class="seal">❧</div><h2>${current().length?'Книг не знайдено':'Ваша історія починається тут'}</h2><p>${current().length?'Спробуйте інший запит або скиньте фільтри.':'Додайте першу книгу, улюблену цитату чи майбутню пригоду.'}</p><button class="primary" id="emptyAdd">＋ Додати книгу</button></div>`;$('#emptyAdd').onclick=()=>editBook();return}const groups=new Map();for(const b of result){const keys=group?(group==='genres'?b.work.genres:[group==='status'?b.status:b.work[group]]):[''];for(const k of keys.length?keys:['Не зазначено']){const label=k||'Не зазначено';if(!groups.has(label))groups.set(label,[]);groups.get(label).push(b)}}$('#content').innerHTML=[...groups].map(([k,v])=>`${group?`<h2 class="group-title">${esc(k)} <small>· ${v.length}</small></h2>`:''}<div class="book-${view}">${v.map(bookCard).join('')}</div>`).join('');bindBooks()}
function bindBooks(root=$('#content')){root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openBook(b.dataset.open));root.querySelectorAll('[data-author]').forEach(b=>b.onclick=()=>{filters.authors=b.dataset.author;page='library';render()});root.querySelectorAll('[data-genre]').forEach(b=>b.onclick=()=>{$('#modal').close();filters.genres=b.dataset.genre;page='library';render()})}
function seriesFor(b){return seriesCatalog.find(s=>norm(s.name)===norm(b.work.series)&&norm(s.authors)===norm(b.work.authors)&&s.books.some(x=>norm(x.original)===norm(b.work.original)||norm(x.title)===norm(b.title)))}function seriesHTML(s){const all=current();const find=x=>all.find(b=>(norm(b.work.original)===norm(x.original)&&norm(b.work.authors)===norm(s.authors))||(norm(b.title)===norm(x.title)&&norm(b.work.authors)===norm(s.authors)));const next=s.books.find(x=>find(x)?.status!=='Прочитано');return `<div class="series-card"><h2>${esc(s.name)}</h2><p>${esc(s.reason)}</p><small>Порядок публікації та основна хронологія цієї трилогії збігаються.</small>${s.books.map(x=>{const b=find(x);return `<div class="series-line"><div><p>${x.order}. ${esc(x.title)} ${x===next?'· <b>Читати далі</b>':''}</p><small>${x.year} · ${b?esc(b.status)+' · У колекції':'Немає в колекції'}${x.order>1?' · Пряме продовження попередньої частини':''}</small></div>${b?`<button data-open="${b.id}">Відкрити</button>`:`<button data-recommend="${s.books.indexOf(x)}">Додати до бажаного</button>`}</div>`}).join('')}<details><summary>Самостійні романи того самого світу</summary>${s.related.map((x,i)=>`<div class="series-line"><div><p>${esc(x.title)}</p><small>${esc(x.relation)} · ${x.year}</small></div><button data-related="${i}">Додати до бажаного</button></div>`).join('')}</details><p><small>Джерело: <a href="${s.source}" target="_blank" rel="noopener">офіційна бібліографія автора</a> · перевірено ${s.verified}. Українські назви слід звіряти з вашим виданням.</small></p></div>`}function bindSeries(root,s){bindBooks(root);root.querySelectorAll('[data-recommend],[data-related]').forEach(btn=>btn.onclick=async()=>{if(demo){toast('Перейдіть до своєї колекції, щоб додати рекомендацію');return}const related=btn.hasAttribute('data-related'),x=(related?s.related:s.books)[+(related?btn.dataset.related:btn.dataset.recommend)];const existing=books.find(b=>norm(b.work.original)===norm(x.original)&&norm(b.work.authors)===norm(s.authors));if(existing){toast('Книга вже є у вашій колекції');return}try{await persist([...books,{...blank(),title:x.title,work:{original:x.original,authors:s.authors,year:x.year,genres:[],series:related?'':s.name,order:related?'':x.order}}]);toast('Додано до бажаного');$('#modal').close();render()}catch{toast('Не вдалося зберегти книгу')}})}function renderSeries(){const represented=seriesCatalog.filter(s=>current().some(b=>seriesFor(b)===s));const unknown=values('series').filter(n=>!represented.some(s=>s.name===n));$('#count').textContent=`${represented.length+unknown.length} циклів`;$('#content').innerHTML=represented.map(seriesHTML).join('')+unknown.map(n=>`<div class="series-card"><h2>${esc(n)}</h2><p>Недостатньо підтверджених даних про склад і порядок циклу. Ви можете виправити назву й номер вручну на сторінці книги.</p></div>`).join('')||'<div class="empty"><h2>Історії ще попереду</h2><p>Додайте книгу та зазначте її цикл. Підтверджена бібліографія наразі доступна для трилогії «Перший закон».</p></div>';represented.forEach(s=>bindSeries($('#content'),s))}
function renderQuotes(){const rows=current().flatMap(b=>b.quotes.map(q=>({b,q})));$('#count').textContent=rows.length+' цитат';$('#content').innerHTML=rows.length?rows.map(({b,q})=>`<div class="quote"><blockquote>«${esc(q.text)}»</blockquote><button data-open="${b.id}">${esc(b.title)} · ${esc(b.work.authors)}</button><small>${q.location?' · '+esc(q.location):''}</small>${q.comment?`<p>${esc(q.comment)}</p>`:''}</div>`).join(''):'<div class="empty"><h2>Слова, що залишаться</h2><p>Відкрийте книгу, щоб додати першу улюблену цитату.</p></div>';bindBooks()}
function openBook(id){const b=current().find(b=>String(b.id)===String(id));if(!b)return;scrollY=window.scrollY;const s=seriesFor(b);modal(head('Сторінка книги')+`<div class="detail"><div class="cover-side">${cover(b)}<div class="actions"><button id="edit">Редагувати</button>${!demo?'<button id="delete">Видалити</button>':''}</div></div><div><div class="eyebrow">${b.favorite?'УЛЮБЛЕНА КНИГА':'З ОСОБИСТОГО АЛЬБОМУ'}</div><h2>${esc(b.title)}</h2><p class="original">${esc(b.work.original)}</p><button class="link" data-author="${esc(b.work.authors)}">${esc(b.work.authors||'Автор не зазначений')}</button><p>${b.work.year?'Перша публікація: '+esc(b.work.year):'Рік першої публікації не зазначений'}${b.edition.year?' · Видання: '+esc(b.edition.year):''}</p><div>${b.work.genres.map(g=>`<button class="chip" data-genre="${esc(g)}">${esc(g)}</button>`).join('')}</div><p><span class="stars">${stars(b)}</span>　<span class="status">${esc(b.status)}</span></p><p>${b.owned?'Є в домашній бібліотеці':'Немає примірника вдома'}</p><section><h3>Анотація</h3><button id="annotationToggle"></button><p id="annotation" style="white-space:pre-wrap">${esc(b.annotation||'Анотацію ще не додано.')}</p></section><section><h3>Особисті нотатки</h3><p style="white-space:pre-wrap">${esc(b.notes||'Тут буде місце для ваших думок.')}</p></section><section><h3>Улюблені цитати</h3><div id="bookQuotes">${b.quotes.map((q,i)=>`<div class="quote"><blockquote>«${esc(q.text)}»</blockquote><small>${esc(q.location)}</small><p>${esc(q.comment)}</p>${!demo?`<button data-quote="${i}">Редагувати</button><button data-delquote="${i}">Видалити</button>`:''}</div>`).join('')||'<p>Ще немає цитат.</p>'}</div>${!demo?'<button id="addQuote">＋ Додати цитату</button>':''}</section><details><summary>Дані видання</summary>${Object.entries({ISBN:b.edition.isbn,'Видавництво':b.edition.publisher,'Перекладач':b.edition.translator,'Мова':b.edition.language}).map(([k,v])=>`<p>${k}: ${esc(v||'Не зазначено')}</p>`).join('')}</details></div></div><section>${s?seriesHTML(s):`<h3>Книжковий цикл</h3><p>${esc(b.work.series?b.work.series+' · № '+(b.work.order||'не зазначено'):'Цикл не зазначено')}. Недостатньо підтверджених даних для рекомендації продовження.</p>`}</section>`);const key='annotation-'+b.id;let expanded=localStorage.getItem(key)==='true';function ann(){$('#annotation').hidden=!expanded;$('#annotationToggle').textContent=expanded?'Згорнути анотацію':'Показати анотацію';$('#annotationToggle').setAttribute('aria-expanded',expanded)}ann();$('#annotationToggle').onclick=()=>{expanded=!expanded;localStorage.setItem(key,expanded);ann()};$('#edit').onclick=()=>{if(demo){toast('Демонстраційні книги доступні лише для перегляду');return}editBook(b)};$('#delete')?.addEventListener('click',async()=>{const old=books;try{await persist(books.filter(x=>x.id!==b.id));$('#modal').close();render();toast('Книгу видалено',async()=>{await persist(old);render();toast('Книгу відновлено')})}catch{toast('Не вдалося видалити книгу')}});$('#addQuote')?.addEventListener('click',()=>quoteForm(b));$('#modal').querySelectorAll('[data-quote]').forEach(x=>x.onclick=()=>quoteForm(b,+x.dataset.quote));$('#modal').querySelectorAll('[data-delquote]').forEach(x=>x.onclick=async()=>{const old=books;try{const n={...b,quotes:b.quotes.filter((_,i)=>i!==+x.dataset.delquote)};await persist(books.map(v=>v.id===b.id?n:v));openBook(b.id);toast('Цитату видалено',async()=>{await persist(old);openBook(b.id);toast('Цитату відновлено')})}catch{toast('Не вдалося зберегти')}});bindBooks($('#modal'));$('#modal').querySelectorAll('[data-author]').forEach(x=>x.onclick=()=>{$('#modal').close();filters.authors=x.dataset.author;page='library';render()});if(s)bindSeries($('#modal'),s)}
function quoteForm(b,index){const q=b.quotes[index]||{text:'',location:'',comment:''};modal(head(index==null?'Нова цитата':'Редагувати цитату')+`<form id="quoteForm"><label class="field">Текст цитати<textarea name="text" required>${esc(q.text)}</textarea></label><label class="field">Сторінка або розділ<input name="location" value="${esc(q.location)}"></label><label class="field">Ваш коментар<textarea name="comment">${esc(q.comment)}</textarea></label><div class="actions"><button class="primary">Зберегти цитату</button><button type="button" id="backBook">Назад до книги</button></div><p class="error" id="formError"></p></form>`);$('#backBook').onclick=()=>openBook(b.id);$('#quoteForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const quotes=[...b.quotes];if(index==null)quotes.push(f);else quotes[index]=f;try{await persist(books.map(x=>x.id===b.id?{...x,quotes}:x));openBook(b.id);toast('Цитату збережено')}catch{$('#formError').textContent='Збереження не вдалося. Текст залишається у формі.'}}}
function blank(){return{id:crypto.randomUUID(),title:'',work:{original:'',authors:'',year:'',genres:[],series:'',order:''},edition:{year:'',isbn:'',publisher:'',translator:'',language:''},status:'Хочу прочитати',rating:null,owned:false,favorite:false,notes:'',annotation:'',quotes:[],cover:'',color:'#385147',added:Date.now()}}
function editBook(existing,fromSearch){const b=structuredClone(existing||blank());if(!existing&&fromSearch){b.title=fromSearch.title;b.work.authors=fromSearch.authors;b.work.year=fromSearch.year}const input=(name,label,value,type='text')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${name==='title'?'required':''}></label>`;modal(head(existing?'Редагувати книгу':'Додати книгу')+`<details ${!existing?'open':''}><summary>Знайти метадані книги</summary><div class="search-row"><label class="search"><input id="metadataQuery" placeholder="Назва, автор або ISBN" aria-label="Пошук метаданих"></label><button type="button" id="metadataSearch">Знайти</button></div><p style="font-size:11px">Open Library: результати описують твір, мова й конкретне видання можуть відрізнятися. Перевірте назву та заповніть видання вручну.</p><div id="metadataResults"></div></details><form id="bookForm"><div class="form-grid">${input('title','Назва українською *',b.title)}${input('authors','Автори (через кому)',b.work.authors)}<label class="field">Статус<select name="status">${statuses.map(s=>`<option ${s===b.status?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Моя оцінка<select name="rating"><option value="">Без оцінки</option>${Array.from({length:9},(_,i)=>1+i*.5).map(v=>`<option value="${v}" ${b.rating===v?'selected':''}>${v.toLocaleString('uk')} / 5</option>`).join('')}</select></label><label><input type="checkbox" name="owned" ${b.owned?'checked':''}> Є в моїй домашній бібліотеці</label><label><input type="checkbox" name="favorite" ${b.favorite?'checked':''}> Улюблена</label><label class="field wide">Моя обкладинка<input type="file" id="coverUpload" accept="image/*"></label><div id="coverPreview" style="max-width:130px">${b.cover?cover(b):''}</div><div class="wide" id="cropArea" hidden><p>Перемістіть кадр повзунками та підтвердьте обкладинку.</p><div class="crop-wrap"><canvas id="cropCanvas" width="400" height="600"></canvas></div><label class="field">Масштаб<input type="range" id="cropZoom" min="1" max="3" step=".01" value="1"></label><label class="field">Горизонталь<input type="range" id="cropX" min="0" max="100" value="50"></label><label class="field">Вертикаль<input type="range" id="cropY" min="0" max="100" value="50"></label><button type="button" id="applyCrop">Застосувати кадрування</button></div></div><details><summary>Більше деталей</summary><div class="form-grid">${input('original','Оригінальна назва',b.work.original)}${input('year','Рік першої публікації твору',b.work.year,'number')}${input('genres','Жанри (через кому)',b.work.genres.join(', '))}${input('series','Цикл',b.work.series)}${input('order','Номер у циклі',b.work.order,'number')}${input('editionYear','Рік конкретного видання',b.edition.year,'number')}${input('isbn','ISBN',b.edition.isbn)}${input('publisher','Видавництво',b.edition.publisher)}${input('translator','Перекладач',b.edition.translator)}${input('language','Мова видання',b.edition.language)}<label class="field wide">Анотація<textarea name="annotation">${esc(b.annotation)}</textarea></label><label class="field wide">Особисті нотатки<textarea name="notes">${esc(b.notes)}</textarea></label>${!existing?'<label class="field wide">Перша улюблена цитата<textarea name="quote"></textarea></label>'+input('quoteLocation','Сторінка або розділ','')+input('quoteComment','Коментар до цитати',''):''}</div></details><div id="duplicateWarning"></div><p id="formError" class="error"></p><div class="actions"><button class="primary" type="submit">Зберегти книгу</button><button type="button" id="cancelForm">Скасувати</button></div></form>`);let coverData=b.cover,confirmedDuplicate=false,cropPending=false;$('#cancelForm').onclick=()=>existing?openBook(existing.id):$('#modal').close();let controller;$('#metadataSearch').onclick=async()=>{const q=$('#metadataQuery').value.trim();if(!q)return;controller?.abort();controller=new AbortController();$('#metadataResults').textContent='Шукаємо…';try{const results=await searchMetadata(q,controller.signal);const root=$('#metadataResults');if(!root)return;root.innerHTML=results.length?results.map((r,i)=>`<div class="series-line"><div><b>${esc(r.title)}</b><p>${esc(r.authors)} · ${esc(r.year||'Рік не зазначений')}</p><a href="https://openlibrary.org${esc(r.key)}" target="_blank" rel="noopener">Джерело</a></div><button type="button" data-result="${i}">Вибрати</button></div>`).join(''):'Нічого не знайдено. Ви можете додати книгу вручну.';root.querySelectorAll('button').forEach(x=>x.onclick=()=>{const r=results[+x.dataset.result],f=$('#bookForm');f.elements.title.value=r.title;f.elements.authors.value=r.authors;f.elements.year.value=r.year;toast('Дані перенесено. Перевірте українську назву та конкретне видання.')})}catch(e){if($('#metadataResults'))$('#metadataResults').textContent=e.name==='AbortError'?'Пошук скасовано.':'Пошук недоступний. Спробуйте пізніше або додайте книгу вручну.'}};$('#coverUpload').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>20*1024*1024){toast('Виберіть зображення до 20 МБ');return}try{const image=await createImageBitmap(file);cropPending=true;$('#cropArea').hidden=false;const c=$('#cropCanvas'),ctx=c.getContext('2d');const draw=()=>{const scale=Math.max(400/image.width,600/image.height)*+$('#cropZoom').value;const w=image.width*scale,h=image.height*scale;ctx.clearRect(0,0,400,600);ctx.drawImage(image,(400-w)*$('#cropX').value/100,(600-h)*$('#cropY').value/100,w,h)};['#cropZoom','#cropX','#cropY'].forEach(s=>$(s).oninput=draw);draw();$('#applyCrop').onclick=()=>{coverData=c.toDataURL('image/jpeg',.88);cropPending=false;$('#coverPreview').innerHTML=`<img class="cover" src="${coverData}" alt="Попередній перегляд обкладинки">`;$('#cropArea').hidden=true;image.close()}}catch{toast('Не вдалося відкрити зображення')}};$('#bookForm').oninput=()=>confirmedDuplicate=false;$('#bookForm').onsubmit=async e=>{e.preventDefault();if(cropPending){$('#formError').textContent='Спочатку застосуйте кадрування обкладинки.';return}const d=Object.fromEntries(new FormData(e.target));if(!d.title.trim())return;const duplicate=books.find(x=>x.id!==b.id&&(norm(x.title)===norm(d.title)||(d.isbn&&x.edition.isbn===d.isbn)));if(duplicate&&!confirmedDuplicate){$('#duplicateWarning').innerHTML='<p class="notice">Схожа книга вже є: '+esc(duplicate.title)+'. Якщо це інше видання, натисніть «Зберегти книгу» ще раз. Автоматичного об’єднання не буде.</p>';confirmedDuplicate=true;return}const n={...b,title:d.title.trim(),cover:coverData,work:{original:d.original.trim(),authors:d.authors.trim(),year:d.year?+d.year:'',genres:d.genres.split(',').map(s=>s.trim()).filter(Boolean),series:d.series.trim(),order:d.order?+d.order:''},edition:{year:d.editionYear?+d.editionYear:'',isbn:d.isbn.trim(),publisher:d.publisher.trim(),translator:d.translator.trim(),language:d.language.trim()},status:d.status,rating:d.rating?+d.rating:null,owned:!!d.owned,favorite:!!d.favorite,annotation:d.annotation,notes:d.notes,quotes:existing?b.quotes:d.quote?.trim()?[{text:d.quote.trim(),location:d.quoteLocation,comment:d.quoteComment}]:[]};for(const catalog of seriesCatalog){const match=catalog.books.find(x=>[x.title,x.original].some(t=>norm(t)===norm(n.title)||norm(t)===norm(n.work.original)));if(match&&norm(n.work.authors)===norm(catalog.authors)&&!n.work.series){n.work.series=catalog.name;n.work.order=match.order;if(!n.work.original)n.work.original=match.original}}try{await persist(existing?books.map(x=>x.id===b.id?n:x):[...books,n]);demo=false;page='library';$('#modal').close();render();toast('Книгу збережено')}catch{$('#formError').textContent='Не вдалося зберегти. Перевірте вільне місце у браузері. Усі введені дані залишилися у формі.'}}}
$('#add').onclick=()=>editBook();$('#personal').onclick=()=>{demo=false;filters={};render()};$('#demo').onclick=()=>{demo=true;filters={};render()};$('#search').oninput=e=>{query=e.target.value;render()};$('#grid').onclick=()=>{view='grid';remember();render()};$('#list').onclick=()=>{view='list';remember();render()};$('#sort').onchange=e=>{sort=e.target.value;remember();render()};$('#direction').onclick=()=>{direction*=-1;remember();render()};$('#group').onchange=e=>{group=e.target.value;render()};$('#filterToggle').onclick=()=>{$('#filters').hidden=!$('#filters').hidden;$('#filterToggle').setAttribute('aria-expanded',!$('#filters').hidden)};$('#reset').onclick=()=>{filters={};group='';$('#group').value='';query='';$('#search').value='';render()};$('#modal').addEventListener('close',()=>window.scrollTo(0,scrollY));$('#backup').onclick=()=>{const blob=new Blob([JSON.stringify({format:'home-library-v1',created:new Date().toISOString(),books})],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='domashnia-biblioteka-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Експортовано вашу колекцію разом з обкладинками')};$('#restore').onclick=()=>$('#restoreFile').click();$('#restoreFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const next=validateBackup(JSON.parse(await f.text()));modal(head('Відновити бібліотеку')+`<p>У копії ${next.length} книг. Відновлення замінить поточну особисту колекцію. Спочатку ви можете експортувати її.</p><div class="actions"><button class="primary" id="confirmRestore">Відновити копію</button><button id="cancelRestore">Скасувати</button></div><p class="error" id="restoreError"></p>`);$('#cancelRestore').onclick=()=>$('#modal').close();$('#confirmRestore').onclick=async()=>{const old=books;try{await persist(next);demo=false;$('#modal').close();render();toast('Бібліотеку відновлено',async()=>{await persist(old);render();toast('Відновлення скасовано')})}catch{$('#restoreError').textContent='Відновлення не вдалося. Поточні дані збережено.'}}}catch(err){toast('Не вдалося прочитати копію: '+err.message)}e.target.value=''};try{books=await openDB();demo=!books.length;render()}catch{$('#content').innerHTML='<div class="empty"><h2>Сховище недоступне</h2><p>Дозвольте локальне збереження даних у налаштуваннях браузера й оновіть сторінку.</p></div>';$('#add').disabled=true}
